package dev.alien.client.studio;
import dev.alien.client.AlienClient;import dev.alien.client.config.*;import dev.alien.client.edition.BuildEdition;import dev.alien.client.gui.*;import dev.alien.client.gui.ui.ModernTextField;import dev.alien.client.module.ModuleManager;
import net.minecraft.client.gui.*;import net.minecraft.util.*;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.texture.DynamicTexture;import org.lwjgl.input.*;import java.io.*;import java.util.*;import javax.imageio.ImageIO;
/** Offline Unified profiles with a truthful change preview and actual framebuffer thumbnails. */
public final class ProfileLibraryScreen extends PremiumScreen {
 private final GuiScreen parent;private ModernTextField name;private java.util.List<String> names;private String selected="",message="",loaded="";private ClientConfig preview;private int left,w,scroll;private final Map<String,ResourceLocation> photos=new HashMap<String,ResourceLocation>();private String pendingDelete="";private int[] previewDiff=new int[3];private final java.util.List<String> previewLines=new ArrayList<String>();
 public ProfileLibraryScreen(GuiScreen p){parent=p;}
 private ConfigStore store(){return AlienClient.get().store();}
 @Override public void initGui(){fontRendererObj=Ui.font();Keyboard.enableRepeatEvents(true);w=Math.min(660,width-24);left=(width-w)/2;name=new ModernTextField(1,fontRendererObj,left+8,40,w/2-12,23).placeholder("Profile name");name.setMaxStringLength(48);name.setText(selected.isEmpty()?"my_profile":selected);rebuild();}
 private void rebuild(){buttonList.clear();previewLines.clear();if(preview!=null){previewDiff=changes(store().config(),preview);java.util.List<StudioModules.Entry> all=StudioModules.entries(preview,manager(preview));for(String category:new String[]{"Render","Player","HUD","Combat"}){StringBuilder text=new StringBuilder(category+" / ");for(StudioModules.Entry e:all)if(category.equals(e.category)&&e.enabled())text.append(e.title).append("  ");previewLines.add(text.toString());}}names=store().listProfiles();int half=(w-8)/2;buttonList.add(new Ui.Button(0,left+w-69,9,69,21,"Back"));buttonList.add(new Ui.Button(1,left+half+8,40,half,23,"Save current as new"));if(selected.isEmpty()){buttonList.add(new Ui.Button(2,left,72,half,22,"Create Alien presets"));buttonList.add(new Ui.Button(3,left+half+8,72,half,22,"Import clipboard JSON"));int cw=(w-12)/2;for(int i=0;i<names.size();i++)buttonList.add(new Ui.Button(100+i,left+(i%2)*(cw+12),105+i/2*35-scroll,cw,29,names.get(i)));}else{String[] labels={"Load profile","Duplicate","Rename","Export JSON file","Copy JSON / share","Capture current frame","Delete (click twice)","Library"};for(int i=0;i<labels.length;i++)buttonList.add(new Ui.Button(10+i,left+(i%2)*(half+8),height-111+i/2*25,half,21,labels[i]));}}
 private ModuleManager manager(ClientConfig c){return ModuleManager.visuals(()->c,BuildEdition.ALLOW_FULL);}
 public static int[] changes(ClientConfig current,ClientConfig next){Set<String> a=StudioModules.enabled(current,ModuleManager.visuals(()->current,BuildEdition.ALLOW_FULL)),b=StudioModules.enabled(next,ModuleManager.visuals(()->next,BuildEdition.ALLOW_FULL));int on=0,off=0;for(String id:b)if(!a.contains(id))on++;for(String id:a)if(!b.contains(id))off++;return new int[]{on,off,b.size()};}
 @Override protected void actionPerformed(GuiButton b){try{if(b.id==0){mc.displayGuiScreen(parent);return;}String target=name.getText().trim();if(b.id==1){if(store().listProfiles().contains(target))throw new IOException("Choose a new name to keep the existing profile");store().saveProfile(target);selected="";message="Saved "+target;}if(b.id==2){for(String preset:new String[]{"Lilac","Night","Clean"}){String id="Alien_"+preset;if(store().listProfiles().contains(id))continue;ClientConfig p=new com.google.gson.Gson().fromJson(new com.google.gson.Gson().toJson(store().config()),ClientConfig.class);p.scenes.enabled=!preset.equals("Clean");p.scenes.sky=preset.equals("Night")?"Nocturne":preset.equals("Lilac")?"Amethyst":"Off";p.scenes.mist=preset.equals("Night");p.scenes.afterglow=preset.equals("Night");p.scenes.radiance=preset.equals("Night");p.hud.applyPreset(preset.equals("Clean")?"Cinematic":"PvP");p.normalize();store().importProfileJson(id,new com.google.gson.Gson().toJson(p));}message="Three local presets created";}
 if(b.id==3){store().importProfileJson(target,GuiScreen.getClipboardString());message="Imported validated JSON as "+target;}
 if(b.id>=100){selected=names.get(b.id-100);pendingDelete="";preview=store().previewProfile(selected);initGui();return;}
 if(b.id==10){if(!store().loadProfile(selected))throw new IOException("Profile not found");loaded=selected;preview=store().previewProfile(selected);message=selected+" is now in use";}
 if(b.id==11){store().duplicateProfile(selected,target);message="Duplicated as "+target;}
 if(b.id==12){store().renameProfile(selected,target);selected=target;preview=store().previewProfile(selected);message="Renamed to "+target;}
 if(b.id==13)message="Exported "+store().exportProfile(selected).getName();
 if(b.id==14){GuiScreen.setClipboardString(store().profileJson(selected));message="JSON copied; paste to share/import locally";}
 if(b.id==15){File root=store().directory();ScreenShotHelper.saveScreenshot(root,"profile-"+selected+".png",mc.displayWidth,mc.displayHeight,mc.getFramebuffer());ResourceLocation previous=photos.remove(selected);if(previous!=null)mc.getTextureManager().deleteTexture(previous);message="Saved the actual current framebuffer";}
 if(b.id==16){if(!selected.equals(pendingDelete)){pendingDelete=selected;message="Click Delete again to remove "+selected;}else{store().deleteProfile(selected);selected="";preview=null;pendingDelete="";message="Profile deleted";}}
 if(b.id==17){selected="";preview=null;scroll=0;}
 rebuild();}catch(Exception failure){message=failure.getMessage()==null?failure.getClass().getSimpleName():failure.getMessage();}}
 @Override public void drawContents(int mx,int my,float partial){Ui.background(width,height);Ui.text("ALIEN / CONFIG LIBRARY",left,15,Ui.theme().text);name.drawTextBox();if(selected.isEmpty()){Ui.text("Local Unified profiles / "+names.size()+" saved",left,97,Ui.theme().muted);float scale=framebufferScale();org.lwjgl.opengl.GL11.glEnable(org.lwjgl.opengl.GL11.GL_SCISSOR_TEST);org.lwjgl.opengl.GL11.glScissor(Math.round(left*scale),Math.round(30*scale),Math.round(w*scale),Math.round(Math.max(0,height-135)*scale));for(GuiButton b:buttonList)if(b.id>=100)b.drawButton(mc,mx,my);org.lwjgl.opengl.GL11.glDisable(org.lwjgl.opengl.GL11.GL_SCISSOR_TEST);}else if(preview!=null){int[] diff=previewDiff;int y=77;Ui.card(left,y,w,Math.max(47,height-196));Ui.text(selected+(selected.equals(loaded)?" / IN USE":" / LOCAL PROFILE"),left+12,y+11,Ui.theme().text);Ui.text("Loading enables "+diff[0]+", disables "+diff[1]+" switches",left+12,y+28,Ui.accent());Ui.text(diff[2]+" active settings / full Unified profile",left+12,y+44,Ui.theme().muted);if(height>310){int yy=y+65;for(String text:previewLines){Ui.text(Ui.font().trimStringToWidth(text,w-30),left+12,yy,Ui.theme().muted);yy+=17;}}photo(left+w-95,y+8,80,45);}
 for(GuiButton b:buttonList)if(b.id<100)b.drawButton(mc,mx,my);Ui.text(Ui.font().trimStringToWidth(message,w),left,height-13,Ui.theme().muted);}
 private void photo(int x,int y,int w,int h){try{ResourceLocation texture=photos.get(selected);if(texture==null){File f=new File(store().directory(),"screenshots/profile-"+selected+".png");if(!f.isFile()||f.length()>16000000)return;java.awt.image.BufferedImage im=ImageIO.read(f);if(im==null||im.getWidth()>4096||im.getHeight()>4096)return;texture=mc.getTextureManager().getDynamicTextureLocation("profile_photo",new DynamicTexture(im));photos.put(selected,texture);}GlStateManager.color(1,1,1,1);mc.getTextureManager().bindTexture(texture);Gui.drawScaledCustomSizeModalRect(x,y,0,0,w,h,w,h,w,h);}catch(IOException ignored){}}
 @Override protected void keyTyped(char ch,int key)throws IOException{if(key==Keyboard.KEY_ESCAPE){if(!selected.isEmpty()){selected="";preview=null;rebuild();}else mc.displayGuiScreen(parent);return;}name.textboxKeyTyped(ch,key);}
 @Override protected void mouseClicked(int x,int y,int button)throws IOException{name.mouseClicked(x,y,button);for(GuiButton b:buttonList)if((b.id<100||(y>=105&&y<height-30))&&b.mousePressed(mc,x,y)){actionPerformed(b);break;}}
 @Override public void handleMouseInput()throws IOException{super.handleMouseInput();int wheel=Mouse.getEventDWheel();if(wheel!=0&&selected.isEmpty()){scroll=Math.max(0,Math.min(Math.max(0,((names.size()+1)/2)*35-(height-135)),scroll+(wheel<0?35:-35)));rebuild();}}
 @Override public void onGuiClosed(){Keyboard.enableRepeatEvents(false);for(ResourceLocation t:photos.values())mc.getTextureManager().deleteTexture(t);photos.clear();}
 @Override public boolean doesGuiPauseGame(){return false;}
}
